 if cross:s+=f'<path d="{dentin}" fill="url(#{id}d)"/><path d="{pulp}" fill="url(#{id}p)"/>'
 else:s+='<path d="M -83 19 C -115 63 -91 99 -82 115" stroke="white" stroke-width="13" opacity=".54" fill="none" stroke-linecap="round"/><path d="M -31 34 Q 0 56 31 34" stroke="#b29b7c" stroke-width="5" fill="none" stroke-linecap="round"/><path d="M -44 52 Q 0 74 44 52" stroke="#fff" stroke-width="4" opacity=".7" fill="none"/>'
